import { expect, expectStatus, test, type Document, type Vendor } from "../../fixtures";

test.describe("vendor lifecycle", () => {
  test("after a replacement, only the new document waits for review", { tag: "@LIF-05" }, async ({ factory, apiAs }) => {
    // Arrange: a vendor in review, with insurance and contract approved and the w9 rejected
    const { vendor, extractions } = await factory.vendorInReview({ as: "member" });
    const reviewer = await apiAs("reviewer");
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
        data: { decision: "approve" },
      }),
      200,
    );
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
        data: { decision: "approve" },
      }),
      200,
    );
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
        data: { decision: "reject", note: "W-9 is unsigned" },
      }),
      200,
    );

    // Act: the member replaces the w9, waits for extraction, and submits again
    const member = await apiAs("member");
    const replacement: Document = await factory.upload(vendor.id, "w9");
    await expect
      .poll(
        async () =>
          (await expectStatus<Document>(await member.get(`/api/documents/${replacement.id}`), 200)).status,
        { message: "replacement w9 is extracted", timeout: 30_000 },
      )
      .toBe("extracted");
    const submitted = await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);

    // Assert: the stored vendor is in review, and the queue holds exactly one pending extraction, the w9
    expect(submitted.status).toBe("in_review");
    const stored = await expectStatus<Vendor>(await member.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.status).toBe("in_review");

    const queue = await expectStatus<{ vendor_id: string; extractions: { kind: string; status: string }[] }[]>(
      await reviewer.get("/api/review-queue"),
      200,
    );
    const item = queue.find((entry) => entry.vendor_id === vendor.id);
    expect(item, "vendor is listed in the review queue").toBeDefined();
    const pending = (item?.extractions ?? []).filter((e) => e.status === "pending_review");
    expect(pending.map((e) => e.kind)).toEqual(["w9"]);
  });
});
